import { useState, useEffect } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type AppearanceTheme = 'light' | 'dark' | 'system';

interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  font: string;
}

const themeLabels: Record<AppearanceTheme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<AppearanceTheme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 480,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
        }}
      >
        <h1
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: 22,
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h1>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ fontSize: 14, color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as AppearanceTheme)}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

